"""Durable local snapshots and best-effort upload outside the negotiation loop."""

import json
import os
import threading
from pathlib import Path

import httpx

from .models import MANIFEST_FIELDS, Run, safe_url
from .reconcile import attach_recovered, recovered_result


def _atomic_file(path: Path, content: str) -> None:
    temporary = path.with_name(path.name + ".tmp")
    descriptor = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    try:
        with os.fdopen(descriptor, "w") as stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        if os.name == "posix":
            directory = os.open(path.parent, os.O_RDONLY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
    finally:
        temporary.unlink(missing_ok=True)


def save_snapshot(run: Run, root: Path, *, patch: str | None = None) -> Path:
    validated = Run.model_validate(run.model_dump())
    directory = Path(root) / validated.run_id
    directory.mkdir(parents=True, exist_ok=True, mode=0o700)
    if patch is not None:
        _atomic_file(directory / "source.patch", patch)
    path = directory / "run.json"
    _atomic_file(
        path, json.dumps(validated.model_dump(), ensure_ascii=False, allow_nan=False, separators=(",", ":")) + "\n"
    )
    return path


def load_snapshots(root: Path):
    for path in sorted(Path(root).glob("*/run.json")):
        if path.stat().st_size > 2 * 1024 * 1024:
            raise ValueError("saved snapshot exceeds the size limit")
        run = Run.model_validate_json(path.read_text())
        recovery = path.parent / "reconciliation.json"
        if recovery.is_file():
            if recovery.stat().st_size > 2 * 1024 * 1024:
                raise ValueError("recovery evidence exceeds the size limit")
            outcomes = json.loads(recovery.read_text())
            body = run.model_dump()
            for attempt in body["attempts"]:
                if attempt["session_id"] in outcomes:
                    attach_recovered(attempt, outcomes[attempt["session_id"]])
            run = Run.model_validate(body)
        yield path, run


def save_reconciliation(run: Run, session_id: str, outcome: dict, root: Path) -> Run:
    directory = Path(root) / run.run_id
    directory.mkdir(parents=True, exist_ok=True, mode=0o700)
    path = directory / "reconciliation.json"
    outcomes = json.loads(path.read_text()) if path.is_file() else {}
    outcomes[session_id] = outcome
    body = run.model_dump()
    for attempt in body["attempts"]:
        if attempt["session_id"] in outcomes:
            attach_recovered(attempt, outcomes[attempt["session_id"]])
    enriched = Run.model_validate(body)
    _atomic_file(path, json.dumps(outcomes, allow_nan=False))
    return enriched


def _merge_pending(before: Run, incoming: Run) -> Run:
    previous, submitted = before.model_dump(), incoming.model_dump()
    if any(previous[key] != submitted[key] for key in MANIFEST_FIELDS):
        raise ValueError("pending run manifest is immutable")
    body, evidence = (submitted, previous) if incoming.revision > before.revision else (previous, submitted)
    attempts = {(attempt["attempt_id"], attempt["session_id"]): attempt for attempt in body["attempts"]}
    for attempt in evidence["attempts"]:
        target = attempts.get((attempt["attempt_id"], attempt["session_id"]))
        outcome = recovered_result(attempt)
        if target is not None and attempt["session_id"] and outcome:
            attach_recovered(target, outcome)
    # Preserve object identity when nothing changes: acknowledgements and close() track the
    # actual payload attempted, since additive recovery does not consume writer revisions.
    return before if body == before.model_dump() else Run.model_validate(body)


def upload(run: Run, url: str, token: str, *, timeout=5.0) -> bool:
    target = safe_url(url)
    with httpx.Client(timeout=timeout, follow_redirects=False) as client:
        response = client.put(
            f"{target}/api/runs/{run.run_id}", json=run.model_dump(), headers={"Authorization": f"Bearer {token}"}
        )
    if response.status_code != 200:
        return False
    body = response.json()
    return isinstance(body, dict) and body.get("ok") is True


class Publisher:
    """One pending latest revision per run; unavailable servers retry periodically."""

    def __init__(self, url: str, token: str, *, interval=5.0, timeout=3.0):
        self.url, self.token = safe_url(url), token
        self.interval, self.timeout = interval, timeout
        self.pending = {}
        self.lock = threading.Lock()
        self.wake = threading.Event()
        self.stopped = threading.Event()
        self.attempted = threading.Event()
        self.thread = threading.Thread(target=self._work, daemon=True, name="lab-publisher")
        self.thread.start()

    def submit(self, run: Run):
        snapshot = Run.model_validate(run.model_dump())
        with self.lock:
            before = self.pending.get(run.run_id)
            merged = snapshot if before is None else _merge_pending(before, snapshot)
            if merged is not before:
                self.pending[run.run_id] = merged
                self.attempted.clear()
        self.wake.set()

    def _work(self):
        while not self.stopped.is_set():
            self.wake.wait(self.interval)
            self.wake.clear()
            with self.lock:
                snapshots = list(self.pending.values())
            for run in snapshots:
                try:
                    ok = upload(run, self.url, self.token, timeout=self.timeout)
                except (httpx.HTTPError, ValueError, OSError):
                    ok = False
                if ok:
                    with self.lock:
                        current = self.pending.get(run.run_id)
                        if current is run:
                            self.pending.pop(run.run_id, None)
                if self.stopped.is_set():
                    return
            with self.lock:
                # Signal after every latest pending revision has had at least one upload attempt.
                attempted_snapshots = {run.run_id: run for run in snapshots}
                if all(current is attempted_snapshots.get(run_id) for run_id, current in self.pending.items()):
                    self.attempted.set()

    def close(self):
        # A final join happens only after negotiation. Snapshots remain available to lab sync.
        self.wake.set()
        self.attempted.wait(timeout=self.timeout + 0.1)
        self.stopped.set()
        self.wake.set()
        self.thread.join(timeout=self.timeout + 0.1)


def sync(root: Path, url: str, token: str) -> dict:
    report = {"uploaded": 0, "failed": 0}
    for _, run in load_snapshots(root):
        try:
            success = upload(run, url, token)
        except (httpx.HTTPError, ValueError, OSError):
            success = False
        report["uploaded" if success else "failed"] += 1
    return report
"""Serial experiment instrumentation around the existing official play interface."""

import difflib
import hashlib
import importlib
import ipaddress
import json
import math
import os
import subprocess
import time
import uuid
from datetime import UTC, datetime
from pathlib import Path
from urllib.parse import urljoin, urlsplit

from arena_kit.client import ArenaError
from arena_kit.play import RemoteTable, hosted

from negotiator.play import play_case as play

from .models import MAX_ATTEMPTS, SECRET_KEYS, Quota, Run, check_json, safe_url, utc_now
from .publish import Publisher, save_snapshot


def _git(repo: Path, *args) -> str:
    result = subprocess.run(["git", "-C", str(repo), *args], capture_output=True, check=True)
    return result.stdout.decode("utf-8", errors="replace")


def _private_path(path: str) -> bool:
    parts = Path(path).parts
    return any(
        part.startswith(".env")
        or part == ".lab-secrets.env"
        or part in {".aws", ".codex", ".agents"}
        or SECRET_KEYS.search(part)
        for part in parts
    )


def fingerprint_data(directory: Path) -> str | None:
    if not directory.is_dir():
        return None
    digest = hashlib.sha256()
    for path in sorted(directory.rglob("*")):
        if path.is_symlink():
            raise ValueError("data fingerprint cannot include symbolic links")
        if path.is_file():
            relative = path.relative_to(directory).as_posix().encode()
            digest.update(len(relative).to_bytes(8, "big") + relative)
            content = path.read_bytes()
            digest.update(len(content).to_bytes(8, "big") + content)
    return digest.hexdigest()


def capture_provenance(
    repo: Path, *, data_dir: Path, release_dir: Path | None = None, allow_dirty=False
) -> tuple[dict, str | None]:
    project = Path(repo).resolve()
    repo = Path(_git(repo, "rev-parse", "--show-toplevel").strip())
    commit = _git(repo, "rev-parse", "HEAD").strip()
    dirty = bool(_git(repo, "status", "--porcelain"))
    if dirty and not allow_dirty:
        raise ValueError("working tree is dirty; commit changes or pass --allow-dirty")
    patch = None
    if dirty:
        # Only nonprivate paths enter the local patch; its contents never enter snapshots.
        tracked = _git(repo, "diff", "HEAD", "--name-only", "-z").split("\0")
        tracked = [p for p in tracked if p and not _private_path(p)]
        patch = _git(repo, "diff", "HEAD", "--binary", "--", *tracked) if tracked else ""
        untracked = _git(repo, "ls-files", "--others", "--exclude-standard", "-z").split("\0")
        for name in untracked:
            path = repo / name
            if name and not _private_path(name) and path.is_file() and not path.is_symlink():
                content = path.read_text(errors="replace")
                patch += "".join(
                    difflib.unified_diff(
                        [], content.splitlines(keepends=True), fromfile="/dev/null", tofile="b/" + name
                    )
                )
        # Do not record environment credentials even if someone put them in a source diff.
        for secret in _secret_values():
            patch = patch.replace(secret, "[redacted]")
    lock_root = project
    while not (lock_root / "uv.lock").is_file() and lock_root != repo:
        lock_root = lock_root.parent
    lock = lock_root / "uv.lock"
    base_hash = fingerprint_data(data_dir)
    overlay_hash = fingerprint_data(release_dir) if release_dir else None
    if release_dir is not None and overlay_hash is None:
        raise ValueError("configured data overlay directory is unavailable")
    data_hash = (
        hashlib.sha256(f"base:{base_hash}\nrelease:{overlay_hash}".encode()).hexdigest()
        if base_hash is not None and overlay_hash is not None
        else base_hash
    )
    return (
        {
            "commit": commit,
            "dirty": dirty,
            "patch_sha256": hashlib.sha256(patch.encode()).hexdigest() if patch is not None else None,
            "lock_sha256": hashlib.sha256(lock.read_bytes()).hexdigest() if lock.is_file() else None,
            "data_sha256": data_hash,
        },
        patch,
    )


def _secret_values():
    return [value for key, value in os.environ.items() if SECRET_KEYS.search(key) and len(value) >= 8]


def sanitize(value, *, budget=120000):
    """Remove credential fields, redact known credentials, and cap supplier evidence size."""
    secrets = _secret_values()

    def visit(node, depth=0):
        if depth > 10:
            return "[truncated]"
        if isinstance(node, dict):
            return {
                str(k)[:256]: visit(v, depth + 1)
                for k, v in list(node.items())[:1000]
                if not SECRET_KEYS.search(str(k))
            }
        if isinstance(node, list):
            return [visit(v, depth + 1) for v in node[:1000]]
        if isinstance(node, str):
            for secret in secrets:
                node = node.replace(secret, "[redacted]")
            return node[:65536]
        if node is None or isinstance(node, (int, float, bool)):
            return node if not isinstance(node, (int, float)) or math.isfinite(node) else None
        return "[unsupported value]"

    result = visit(value)
    if len(json.dumps(result, allow_nan=False).encode()) > budget:
        return {"evidence_truncated": True, "note": "Evidence exceeded the snapshot budget; outcome metrics retained."}
    return result


def agent_factory(name: str, config: dict):
    check_json(config)
    if name == "package":
        from negotiator.agent import PackageAgent

        factory = PackageAgent
    elif name == "naive":
        from arena_kit.agents import NaiveAgent

        factory = NaiveAgent
    else:
        module, sep, attribute = name.partition(":")
        if not sep or not module or not attribute.isidentifier():
            raise ValueError("agent must be package, naive or module:factory")
        factory = getattr(importlib.import_module(module), attribute)
    if not callable(factory):
        raise ValueError("agent factory is not callable")

    def create():
        agent = factory(**config)
        if not callable(getattr(agent, "decide", None)):
            raise ValueError("agent must implement decide(case, threads)")
        return agent

    # Validate before opening sessions and reuse that first object, avoiding construction side effects.
    first = [create()]

    def next_agent():
        return first.pop() if first else create()

    return next_agent


def assert_simulator_is_local(environment: str, arena_url: str) -> None:
    if environment != "simulator":
        return
    host = urlsplit(safe_url(arena_url)).hostname
    try:
        local = ipaddress.ip_address(host).is_loopback
    except ValueError:
        local = host == "localhost"
    if not local:
        raise ValueError("simulator runs require a loopback ARENA_URL (localhost, 127.0.0.1 or ::1)")


def plan_run(
    *,
    name,
    author,
    hypothesis,
    agent,
    config,
    cases,
    repetitions,
    max_sessions,
    environment,
    arena_url,
    provenance,
    baseline_id=None,
) -> Run:
    if (
        type(repetitions) is not int
        or type(max_sessions) is not int
        or not cases
        or len(set(cases)) != len(cases)
        or repetitions < 1
        or max_sessions < 1
        or max_sessions > MAX_ATTEMPTS
        or len(cases) * repetitions > max_sessions
    ):
        raise ValueError("case/repetition plan exceeds the explicit session ceiling")
    assert_simulator_is_local(environment, arena_url)
    check_json(config)
    if any(secret in json.dumps(config) for secret in _secret_values()):
        raise ValueError("configuration contains private credentials")
    public_manifest = {
        "name": name,
        "author": author,
        "hypothesis": hypothesis,
        "agent": agent,
        "arena_url": arena_url,
        "baseline_id": baseline_id,
    }
    if any(secret in json.dumps(public_manifest) for secret in _secret_values()):
        raise ValueError("manifest contains private credentials")
    model_environment = {
        key: os.environ[key] for key in ("LLM_PROVIDER", "LLM_MODEL", "LLM_EFFORT") if os.environ.get(key)
    }
    if "_lab_environment" in config:
        raise ValueError("configuration uses a reserved metadata field")
    recorded_config = {**config, **({"_lab_environment": model_environment} if model_environment else {})}
    check_json(recorded_config)
    if any(secret in json.dumps(recorded_config) for secret in _secret_values()):
        raise ValueError("configuration contains private credentials")
    now = utc_now()
    return Run.model_validate(
        {
            "schema_version": 1,
            "run_id": str(uuid.uuid4()),
            "revision": 1,
            "name": name,
            "author": author,
            "hypothesis": hypothesis,
            "agent": agent,
            "config": recorded_config,
            "source": "tracked",
            "environment": environment,
            "arena_url": safe_url(arena_url),
            "baseline_id": baseline_id,
            "started_at": now,
            "updated_at": now,
            "status": "running",
            "cases": cases,
            "repetitions": repetitions,
            "provenance": provenance,
            "quota": None,
            "attempts": [
                {
                    "attempt_id": f"{case}:{repeat}",
                    "case_id": case,
                    "repeat": repeat,
                    "status": "pending",
                    "session_id": None,
                    "replay_url": None,
                    "score": None,
                    "rounds": None,
                    "elapsed_s": None,
                    "timeouts": None,
                    "error": None,
                    "result": {},
                    "threads": {},
                }
                for case in cases
                for repeat in range(1, repetitions + 1)
            ],
        }
    )


def quota_snapshot(client) -> Quota | None:
    try:
        body = client.me()
        practice = body.get("practice", {})
        used = practice.get("used", body.get("practice_sessions_used"))
        left = practice.get("left", body.get("practice_sessions_left"))
        limit = practice.get("limit", body.get("practice_sessions_limit"))
        if limit is None and type(used) is int and type(left) is int:
            limit = used + left
        return Quota.model_validate({"used": used, "left": left, "limit": limit, "checked_at": utc_now()})
    except Exception:
        return None


def replay_url(value, arena_url):
    if not isinstance(value, str) or not value:
        return None
    try:
        full = safe_url(urljoin(arena_url + "/", value))
        arena, target = urlsplit(arena_url), urlsplit(full)
        return full if (target.scheme, target.netloc) == (arena.scheme, arena.netloc) else None
    except ValueError:
        return None


def safe_error(error: Exception | BaseException) -> str:
    if isinstance(error, ArenaError):
        return f"arena request failed (HTTP {error.status}); inspect the arena session before retrying"
    if isinstance(error, KeyboardInterrupt):
        return "run interrupted; inspect the arena session before starting another attempt"
    return f"attempt failed ({type(error).__name__}); inspect the arena session before retrying"


class RecordingTable(RemoteTable):
    def __init__(self, client, attempt, changed):
        super().__init__(client)
        self.attempt, self.changed = attempt, changed
        self.rounds = 0
        self.seen_threads = {}

        self.seen_threads = {}
        # JournaledArena calls this after limiter pacing and its final history read,
        # immediately before persisting the intent and issuing the POST.
        self.client.pre_post_check = self._validate_post_dispatch

    def open(self, case_id):
        case, threads = super().open(case_id)
        self.attempt.session_id = self.session_id
        self.changed()  # durably record identity before documents or the first decision
        self.seen_threads = threads
        observer = getattr(getattr(self, "agent", None), "observe_lab_session", None)
        if callable(observer):
            observer(self.run_id, self.session_id)
        observer = getattr(getattr(self, "agent", None), "observe_lab_acknowledgement", None)
        if callable(observer):
            for supplier in threads:
                observer(supplier, self.client.thread(self.session_id, supplier))
        self._observe_server()
        return case, threads

    def _observe_server(self):
        observer = getattr(getattr(self, "agent", None), "observe_lab_server_state", None)
        if callable(observer):
            agent = self.agent
            if getattr(agent, "requires_complete_history", False):
                for supplier in agent.dataset["case"]["suppliers"]:
                    thread = self.client.thread(self.session_id, supplier)
                    for message in thread["messages"]:
                        for attachment in message.get("attachments", []):
                            attachment_id = attachment["attachment_id"]
                            if attachment_id not in agent.attachment_bytes:
                                agent.observe_lab_attachment(attachment_id,
                                    self.client.attachment(self.session_id, attachment_id))
                    agent.observe_lab_acknowledgement(supplier, thread)
            requested_at = datetime.now(UTC)
            state = self.client.session(self.session_id)
            observer(state, requested_at=requested_at, received_at=datetime.now(UTC))

    def attachment(self, attachment_id):
        content = super().attachment(attachment_id)
        observer = getattr(getattr(self, "agent", None), "observe_lab_attachment", None)
        if callable(observer):
            observer(attachment_id, content)
        return content

    def send(self, supplier_id, message):
        self._validate_dispatch(supplier_id, message)
        self.rounds += 1
        reply = super().send(supplier_id, message)
        observer = getattr(getattr(self, "agent", None), "observe_lab_acknowledgement", None)
        if callable(observer):
            # Read authoritative history only after a successful POST. The kit's play
            # loop also appends local buyer requests after some 409 replies; those do
            # not prove that the requested action was acknowledged.
            observer(supplier_id, self.client.thread(self.session_id, supplier_id))
        self._observe_server()
        return reply

    def close(self, supplier_id, message):
        self._validate_dispatch(supplier_id, message)
        self.rounds += 1
        return super().close(supplier_id, message)

    def _validate_dispatch(self, supplier_id, message):
        validator = getattr(getattr(self, "agent", None), "validate_lab_dispatch", None)
        if callable(validator):
            self._observe_server()
            validator(supplier_id, message, self.client.thread(self.session_id, supplier_id))

    def _validate_post_dispatch(self, supplier_id, message, current_thread):
        validator = getattr(getattr(self, "agent", None), "validate_lab_dispatch", None)
        if callable(validator):
            # Refresh the authoritative session clock after pacing, then take the
            # last thread read used to validate this exact payload.
            self._observe_server()
            thread = self.client.thread(self.session_id, supplier_id)
            validator(supplier_id, message, thread)


def collect_session(client, attempt, arena_url, *, budget, require_complete=False):
    """Only owned session/thread reads, after negotiation; never spectator routes."""
    if not attempt.session_id:
        return
    try:
        state = client.session(attempt.session_id)
        attempt.replay_url = replay_url(state.get("replay_url"), arena_url)
        if type(state.get("rounds")) is int:
            attempt.rounds = max(0, state["rounds"])
        threads, timeouts = {}, 0
        for supplier in list(state.get("threads", {}))[:100]:
            thread = client.thread(attempt.session_id, supplier)
            threads[supplier] = thread
            timeout_values = thread.get("timeouts", [])
            timeouts += len(timeout_values) if isinstance(timeout_values, list) else max(0, int(timeout_values or 0))
        captured = sanitize(threads, budget=budget)
        if require_complete and captured != threads:
            raise ValueError("complete thread evidence exceeds Lab bounds or requires redaction")
        attempt.threads = captured
        attempt.timeouts = timeouts
    except Exception:
        if require_complete:
            raise
        # Failure to read ancillary evidence never invents a negotiation score or overwrites the outcome.
        if not attempt.error:
            attempt.error = "session detail unavailable; outcome retained"


def run_experiment(
    run: Run, root: Path, client, create_agent, *, publisher: Publisher | None = None, patch: str | None = None
) -> Run:
    def persist():
        run.revision += 1
        run.updated_at = utc_now()
        save_snapshot(run, root)
        if publisher:
            publisher.submit(run)

    def session_created():
        left = getattr(client, "practice_remaining", None)
        if run.quota and type(left) is int and 0 <= left <= run.quota.limit and left != run.quota.left:
            run.quota = Quota(used=run.quota.limit - left, left=left, limit=run.quota.limit, checked_at=utc_now())
        persist()

    save_snapshot(run, root, patch=patch)  # before any arena networking
    if publisher:
        publisher.submit(run)
    budget = min(300000, 800000 // len(run.attempts))
    try:
        assert_simulator_is_local(run.environment, run.arena_url)
        first_agent = create_agent()
        if getattr(first_agent, "local_only", False) and run.environment != "simulator":
            raise ValueError("local-only agent requires the simulator environment")
        set_ = "practice" if run.environment == "simulator" else run.environment
        available_cases = {c["case_id"]: c for c in hosted(client.cases(set_))}
        allowed = set(available_cases)
        if not set(run.cases) <= allowed:
            raise ValueError("requested case is not hosted in this environment")
        run.quota = quota_snapshot(client)
        if run.environment == "practice" and run.quota and run.quota.left < len(run.attempts):
            raise ValueError("authoritative practice quota is below the planned session count")
        persist()
        for attempt in run.attempts:
            attempt.status = "running"
            persist()
            table = RecordingTable(client, attempt, session_created)
            started = time.monotonic()
            agent = None
            try:
                agent = first_agent if first_agent is not None else create_agent()
                first_agent = None
                table.agent, table.run_id = agent, run.run_id
                case_validator = getattr(agent, "validate_lab_case", None)
                if callable(case_validator):
                    case_validator(available_cases[attempt.case_id])
                result = play(table, attempt.case_id, agent)
                score = result.get("score")
                if score is not None and (
                    isinstance(score, bool)
                    or not isinstance(score, (int, float))
                    or not math.isfinite(score)
                    or not 0 <= score <= 1
                ):
                    raise ValueError("invalid arena score")
                attempt.result = sanitize(result, budget=budget)
                completed_score = float(score) if score is not None else None
            except KeyboardInterrupt as error:
                attempt.status, attempt.error = "failed", safe_error(error)
                run.status = "interrupted"
                raise
            except Exception as error:
                attempt.status, attempt.error = "failed", safe_error(error)
                if isinstance(error, ArenaError) and error.status == 429:
                    run.status = "failed"
                    break
            finally:
                metrics = getattr(agent, "experiment_metrics", None)
                if callable(metrics):
                    try:
                        attempt.result["agent_metrics"] = sanitize(metrics(), budget=10000)
                    except Exception:
                        attempt.result["agent_metrics"] = {"unavailable": True}
                attempt.elapsed_s = min(604800.0, time.monotonic() - started)
                attempt.rounds = table.rounds
                attempt.threads = sanitize(table.seen_threads, budget=budget)
                # Persist the outcome immediately before ancillary read calls.
                persist()
            complete = getattr(agent, "requires_complete_history", False)
            collect_session(client, attempt, run.arena_url, budget=budget, require_complete=complete)
            observer = getattr(agent, "observe_lab_outcome", None)
            if callable(observer) and attempt.status == "running":
                terminal_observer = getattr(agent, "observe_lab_terminal", None)
                if callable(terminal_observer):
                    terminal_observer(client.session(attempt.session_id))
                attachment_observer = getattr(agent, "observe_lab_attachment", None)
                if callable(attachment_observer):
                    for thread in attempt.threads.values():
                        for message in thread.get("messages", []):
                            for attachment in message.get("attachments", []):
                                attachment_observer(attachment["attachment_id"],
                                    client.attachment(attempt.session_id, attachment["attachment_id"]))
                observer(attempt.result, attempt.threads)
                attempt.result["agent_metrics"] = sanitize(agent.experiment_metrics(), budget=10000)
            evidence = getattr(agent, "experiment_evidence", None)
            if callable(evidence):
                original_evidence = evidence()
                captured = sanitize(original_evidence, budget=800000 if complete else budget)
                if getattr(agent, "requires_complete_history", False) and captured != original_evidence:
                    raise ValueError("complete evidence exceeds Lab bounds or requires redaction; not finalized")
                attempt.result["agent_evidence"] = captured
            if attempt.status == "running":
                attempt.score, attempt.status = completed_score, "completed"
            persist()
        if run.status == "running":
            run.status = "completed" if all(a.status == "completed" for a in run.attempts) else "failed"
    except KeyboardInterrupt:
        run.status = "interrupted"
    except Exception as error:
        run.status = "failed"
        for attempt in run.attempts:
            if attempt.status in {"pending", "running"}:
                attempt.status, attempt.error = "failed", safe_error(error)
    finally:
        run.quota = quota_snapshot(client) or run.quota
        persist()
        if publisher:
            publisher.close()
    return run
"""Prepare or execute ONE explicitly authorized hosted V2 stage through the existing Lab.

Default mode is local preparation only. D01 -> D02 -> P10 requires a fresh evidence review
and authorization for each stage. No session/inference/publication occurs while preparing.
"""

import argparse
import hashlib
import json
import os
import time
from dataclasses import asdict
from decimal import Decimal
from pathlib import Path

import httpx
from arena_kit.cli import load_env
from arena_kit.cost import must_haves_ok

from negotiator.lab.publish import _atomic_file, save_snapshot, upload
from negotiator.lab.runner import capture_provenance, collect_session, plan_run, run_experiment
from negotiator.lab.transport import JournaledArena
from negotiator.v2.core.serialization import semantic_hash
from negotiator.v2.factory import online_lab_agent

from .run_adaptive_milestone import CONFIG, PER_CALL_TOKENS, OfflineAllowance
from .run_adaptive_milestone import plan as offline_plan
from .run_lab_local import PROJECT

STAGES = {"D01": ("sandbox", 18, "1.00", None),
          "D02": ("sandbox", 36, "2.00", "D01"),
          "P10": ("practice", 18, "1.00", "D02")}


def verify_model_access():
    if not os.environ.get("LLM_API_KEY"):
        raise ValueError("LLM_API_KEY missing")
    with httpx.Client(timeout=30, follow_redirects=False) as client:
        response = client.get(CONFIG.base_url + "/models/" + CONFIG.model_id,
                              headers={"Authorization": "Bearer " + os.environ["LLM_API_KEY"]})
        response.raise_for_status()
        if response.json().get("id") != CONFIG.model_id:
            raise ValueError("authorized model metadata mismatch")


def verify_lab_access(url):
    if os.environ.get("LAB_URL", "").rstrip("/") != url.rstrip("/") or not os.environ.get("LAB_UPLOAD_TOKEN"):
        raise ValueError("Lab credentials/destination differ from the explicit allowance")
    with httpx.Client(timeout=30, follow_redirects=False) as client:
        response = client.get(url.rstrip("/") + "/api/runs",
                              headers={"Authorization": "Bearer " + os.environ["LAB_UPLOAD_TOKEN"]})
        response.raise_for_status()
        if not isinstance(response.json().get("runs"), list):
            raise ValueError("normal Lab listing unavailable")


def publish_verified(run, url, output):
    # One final PUT only. No publisher thread or retry; all evidence is already captured.
    if not upload(run, url, os.environ["LAB_UPLOAD_TOKEN"], timeout=30):
        raise ValueError("Lab publication failed; preserve this run, do not repeat negotiation")
    with httpx.Client(base_url=url.rstrip("/"), timeout=30, follow_redirects=False,
                      headers={"Authorization": "Bearer " + os.environ["LAB_UPLOAD_TOKEN"]}) as client:
        listing = client.get("/api/runs")
        listing.raise_for_status()
        response = client.get("/api/runs/" + run.run_id)
        response.raise_for_status()
        body = response.json()
        if body != run.model_dump() or run.run_id not in {r["run_id"] for r in listing.json()["runs"]}:
            raise ValueError("Lab retrieval does not exactly match the completed evidence")
        proof = {"lab_url": url, "run_id": run.run_id, "retrieval_verified": True,
                 "listing_verified": True, "run": body}
        _atomic_file(output / ("lab-proof-" + run.run_id + ".json"), json.dumps(proof, indent=2))
    return proof


def dataset_for(case):
    if case["case_id"] not in {"case:D01", "case:D02", "case:P10"} or len(case["parts"]) != 1:
        raise ValueError("unsupported hosted case/part count")
    # Baseline is a legal buyer-plan package, not a simulator-specific bargaining rule.
    buyer = case["buyer"]
    preferred = {"unit_price": buyer.get("current_unit_price") or buyer["fallback_unit_price"],
                 "payment_days": buyer["reference_payment_days"], "lead_time_days": buyer["need_lead_time_days"],
                 "incoterm": "DAP", "contract_months": round(12 * buyer["horizon_years"]),
                 "volume_per_year": buyer["need_per_year"]}
    terms = {}
    for field in case["negotiable"]:
        choices = case["term_options"].get(field)
        value = preferred.get(field)
        terms[field] = value if not choices or value in choices else choices[0]
    if not must_haves_ok(case, terms):
        raise ValueError("buyer-plan baseline violates must-haves; explicit case support needed")
    return {"case": case, "price_unit": 1, "supplier_messages": [], "candidate_terms": [terms],
            "price_basis_source": "official case briefing: EUR per unit; single part",
            "estimate_limit": "supplier full-cost estimates unavailable; relationship component explicitly unestimated"}


def prior_review(path, stage):
    predecessor = STAGES[stage][3]
    if predecessor is None:
        return None  # Explicit user priority: D01 is the first genuine hosted validation.
    if path is None:
        raise ValueError("prior stage actual transcript and blockers must be reviewed first")
    review = json.loads(path.read_text())
    required = {"stage": predecessor, "transcript_reviewed": True, "blocking_issues_resolved": True,
                "genuine_hosted_model": True, "lab_retrieval_verified": True}
    if any(review.get(key) != value for key, value in required.items()):
        raise ValueError("prior stage actual transcript and blockers must be reviewed first")
    proofs = []
    for artifact in review.get("artifacts", []):
        p = Path(artifact["path"])
        if hashlib.sha256(p.read_bytes()).hexdigest() != artifact["sha256"]:
            raise ValueError("prior reviewed artifact changed")
        content = json.loads(p.read_text())
        if isinstance(content, dict) and content.get("retrieval_verified") is True and "run" in content:
            proofs.append(content)
    if not review.get("artifacts"):
        raise ValueError("review requires actual original evidence artifacts")
    adaptive = [proof["run"] for proof in proofs if proof["run"].get("config", {}).get("arm") == "adaptive"
                or proof["run"].get("environment") in {"sandbox", "practice"}]
    if len(adaptive) != 1:
        raise ValueError("review requires exactly one actual adaptive predecessor Lab retrieval proof")
    run = adaptive[0]
    expected_case = "case:P10" if predecessor == "offline" else "case:" + predecessor
    if run.get("status") != "completed" or run.get("cases") != [expected_case]:
        raise ValueError("predecessor outcome/case does not match the execution order")
    attempt = run["attempts"][0]
    metrics = attempt["result"].get("agent_metrics", {})
    if metrics.get("model") != CONFIG.model_id or not any(
            d.get("proposal_admitted") is True and d.get("interpretation_admitted") is True
            for d in metrics.get("decisions", [])):
        raise ValueError("predecessor requires admitted genuine model interpretation and proposals")
    evidence = attempt["result"].get("agent_evidence", {})
    if predecessor == "offline":
        validation = evidence.get("validation_evidence", {})
        report = json.loads(validation.get("interpretation_report_json", "{}"))
        if report.get("semantic_correct", 0) < 12 or run.get("environment") != "simulator":
            raise ValueError("offline semantic validation and official simulator evidence required")
    else:
        terminal = json.loads(evidence.get("terminal_json", "{}"))
        if run.get("environment") != "sandbox" or terminal.get("state", {}).get("status") != "ended":
            raise ValueError("original ended sandbox terminal evidence required")
    return semantic_hash(review)


def plan(stage, dataset, lab_url, prior_review_hash=None):
    environment, calls, dollars, predecessor = STAGES[stage]
    return {"authorized": False, "token_accounting_confirmed": False,
            "stage": stage, "case": "case:" + stage, "case_hash": semantic_hash(dataset["case"]),
            "dataset_hash": semantic_hash(dataset), "environment": environment,
            "arena_url": "https://arena.tacto.ai", "online_sessions": 1, "remote_writes": 1,
            "lab_url": lab_url, "model_config": asdict(CONFIG), "model_id": CONFIG.model_id,
            "strategy": "bounded-proposal-v1", "max_calls": calls, "max_usd": dollars,
            "max_total_reserved_tokens": calls * PER_CALL_TOKENS,
            "max_output_tokens": CONFIG.max_output_tokens, "retries": 0, "automatic_reruns": 0,
            "source_sha256": offline_plan()["source_sha256"], "prior_stage": predecessor,
            "prior_review_hash": prior_review_hash, "offline_verification": predecessor is not None,
            "direct_sandbox_validation": stage == "D01", "remote_lab_verified": True,
            "token_accounting": offline_plan()["token_accounting"],
            "supplier_estimates": dataset.get("estimate_limit"),
            "review_required": "review this actual D01 transcript before D02" if stage == "D01" else
            "complete predecessor transcript, semantic quality, fallbacks, economics and blockers"}


class SingleSessionArena(JournaledArena):
    def __init__(self, path, case_id, **kwargs):
        super().__init__(path, **kwargs)
        self.case_id = case_id

    def _call(self, method, path, body=None, params=None, raw=False):
        if method == "POST" and path == "/sessions":
            attempted = any(r.get("rec") == "intent" and r.get("path") == "/sessions"
                            for r in self.journal.records)
            if body != {"case_id": self.case_id} or attempted or self.journal.pending():
                raise ValueError("one exact authorized session only; no reopen or retry")
        elif method == "POST":
            owned = self.journal.session_for(self.case_id)
            case = self.journal.case_file(self.case_id) or {}
            permitted = {f"/sessions/{owned}/threads/{supplier}/messages" for supplier in case.get("suppliers", [])}
            if not owned or path not in permitted:
                raise ValueError("submission is outside the authorized owned session/supplier endpoints")
        return super()._call(method, path, body, params, raw)


def capture_failed_terminal(run, client, agent, output, *, wait_seconds=300):
    """Read only the original owned session before its ONE final failure publication."""
    attempt = run.attempts[0]
    if not attempt.session_id:
        return
    deadline = time.monotonic() + wait_seconds
    while True:
        state = client.session(attempt.session_id)
        _atomic_file(output / "failed-owned-state.json", json.dumps(state, indent=2))
        if state.get("status") == "ended":
            collect_session(client, attempt, run.arena_url, budget=300000, require_complete=True)
            for thread in attempt.threads.values():
                for message in thread["messages"]:
                    for att in message.get("attachments", []):
                        if att["attachment_id"] not in agent.attachment_bytes:
                            agent.observe_lab_attachment(att["attachment_id"],
                                client.attachment(attempt.session_id, att["attachment_id"]))
            agent.observe_lab_terminal(state)
            agent.observe_lab_outcome(state["result"], attempt.threads)
            attempt.result.update(state["result"])
            attempt.result["agent_evidence"] = agent.experiment_evidence()
            # Remain failed: a later server timeout is not a completed agent negotiation.
            run.revision += 1
            save_snapshot(run, output / "runs")
            return
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise ValueError(
                "owned terminal outcome still unavailable; preserve run, do not publish incomplete evidence")
        time.sleep(min(30, remaining))


def execute(output, authorization, stage, dataset, lab_url, review_path=None):
    review_hash = prior_review(review_path, stage)
    expected = plan(stage, dataset, lab_url, review_hash)
    approved = json.loads(authorization.read_text())
    if approved != {**expected, "authorized": True, "token_accounting_confirmed": True}:
        raise ValueError("exact source/case/session/inference/Lab-write authorization required")
    load_env()
    if not os.environ.get("LLM_API_KEY") or not os.environ.get("ARENA_API_KEY"):
        raise ValueError("hosted credentials missing")
    if os.environ.get("ARENA_URL", "https://arena.tacto.ai").rstrip("/") != approved["arena_url"]:
        raise ValueError("Arena destination differs from explicit authorization")
    verify_lab_access(lab_url)
    verify_model_access()
    if output.exists():
        raise ValueError("fresh output required; no automatic restart/rerun")
    output.mkdir(parents=True, mode=0o700)
    marker = authorization.with_name(authorization.name + ".consumed")
    with os.fdopen(os.open(marker, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "w") as stream:
        stream.write(semantic_hash(approved))
        stream.flush()
        os.fsync(stream.fileno())
    _atomic_file(output / "approved-plan.json", json.dumps(approved, indent=2))
    _atomic_file(output / "dataset.json", json.dumps(dataset, indent=2))
    allowance = OfflineAllowance(output, max_calls=approved["max_calls"], max_usd=Decimal(approved["max_usd"]))
    client = SingleSessionArena(output / "arena-journal.jsonl", approved["case"],
                                base_url=approved["arena_url"], api_key=os.environ["ARENA_API_KEY"], timeout=180)
    try:
        me = client.me()
        cases = client.cases(approved["environment"])
        actual = next((case for case in cases if case["case_id"] == approved["case"]), None)
        if me.get("status") != "active" or actual != dataset["case"]:
            raise ValueError("current permissions/case differ from reviewed readiness")
        if stage == "P10" and (actual.get("hosted") is not True or me.get("practice", {}).get("left", 0) < 1):
            raise ValueError("practice case/quota unavailable")
        if client.journal.pending():
            raise ValueError("unresolved submission; read-only reconciliation required")
        _atomic_file(output / "preflight.json", json.dumps({"me": me, "case": actual}, indent=2))
        agent = online_lab_agent(dataset_path=output / "dataset.json", trace_root=output / "traces",
                                 transport=allowance, model_config=CONFIG, execution_allowance=approved)
        provenance, patch = capture_provenance(PROJECT, data_dir=output, allow_dirty=True)
        run = plan_run(name="V2 hosted " + stage, author="authorized-v2-validation",
            hypothesis="Real citation-grounded adaptive proposals negotiate using complete official observations.",
            agent="negotiator.v2.factory:online_lab_agent", config={"execution_plan_json": json.dumps(approved)},
            cases=[approved["case"]], repetitions=1, max_sessions=1, environment=approved["environment"],
            arena_url=approved["arena_url"], provenance=provenance)
        final = run_experiment(run, output / "runs", client, lambda: agent, patch=patch)
        if final.status != "completed":
            capture_failed_terminal(final, client, agent, output)
        # Publish original failed attempts too. A failure never authorizes a replacement session.
        publish_verified(final, lab_url, output)
        if final.status != "completed" or allowance.stopped or client.journal.pending():
            raise ValueError("hosted stage failed or uncertain; review original evidence before proceeding")
        _atomic_file(output / "review-required.json", json.dumps({"stage": stage,
            "transcript_reviewed": False, "blocking_issues_resolved": False, "genuine_hosted_model": True,
            "lab_retrieval_verified": True, "artifacts": []}, indent=2))
    finally:
        client.http.close()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--stage", choices=STAGES, required=True)
    parser.add_argument("--metadata", type=Path, required=True)
    parser.add_argument("--lab-url", required=True)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--prior-review", type=Path)
    parser.add_argument("--authorization", type=Path)
    args = parser.parse_args()
    metadata = json.loads(args.metadata.read_text())
    environment = STAGES[args.stage][0]
    case = next(c for c in metadata["cases?set=" + environment] if c["case_id"] == "case:" + args.stage)
    dataset = dataset_for(case)
    review_hash = prior_review(args.prior_review, args.stage) if args.prior_review else None
    if args.authorization:
        if STAGES[args.stage][3] is not None and not args.prior_review:
            raise ValueError("prior actual transcript review required before execution")
        execute(args.out, args.authorization, args.stage, dataset, args.lab_url, args.prior_review)
    else:
        args.out.mkdir(parents=True, exist_ok=True)
        _atomic_file(args.out / "dataset.json", json.dumps(dataset, indent=2))
        _atomic_file(args.out / "authorization-template.json", json.dumps(
            plan(args.stage, dataset, args.lab_url, review_hash), indent=2))
        print("Prepared " + args.stage + "; inference=0; sessions=0; Lab writes=0; explicit approval required")


if __name__ == "__main__":
    main()

