from decimal import Decimal

from ..core import models as m


def supplier_reference(conversation, fields, evaluator, supplier_id, economic):
    """Use the latest complete standing supplier quote; never substitute buyer targets."""
    required = set(fields)
    for message in reversed(conversation.messages):
        if message.speaker != "supplier":
            continue
        for sheet in reversed(message.observed_sheets):
            bindings = sheet.complete_bindings or sheet.bindings
            if sheet.standing and {item.field for item in bindings} == required:
                package = m.Package(bindings=bindings, price_basis=economic.current_price.basis
                                    if economic.current_price else economic.fallback_price.basis)
                try:
                    evaluation = evaluator.evaluate_package(package, supplier_id, economic)
                    nominal = evaluation.nominal_cost.total.amount
                except Exception:
                    nominal = None
                return m.CommercialReference(kind="observed_supplier_offer", bindings=bindings,
                    source_message_id=message.message_id, official_nominal_cost=nominal)
    return m.CommercialReference(kind="unavailable")


def commercial_effects(reference, fields):
    before = {item.field: item for item in reference.bindings}
    descriptions = {
        "unit_price": "Lower price favors buyer; supplier revenue changes, margin and net value unknown.",
        "payment_days": "More days delays supplier receipts; it does not improve supplier cash flow.",
        "contract_months": "Longer commitment may add predictability, but its value is unknown.",
        "lead_time_days": "Shorter lead time favors buyer; supplier cost or feasibility is unknown.",
        "volume_per_year": "Volume changes affect both obligations; supplier net value is unknown.",
    }
    result = []
    for field in fields:
        prior = before.get(field)
        buyer, supplier = "unknown", "unknown"
        if prior is not None and field == "unit_price":
            buyer = "favorable" if prior.value > 0 else "unknown"
            supplier = "potentially_unfavorable"
        elif prior is not None and field == "payment_days":
            buyer = "favorable"
            supplier = "potentially_unfavorable"
        elif prior is not None and field == "contract_months":
            buyer, supplier = "unfavorable", "unknown"
        elif prior is not None and field == "lead_time_days":
            buyer, supplier = "favorable", "unknown"
        result.append(m.CommercialTermEffect(field=field, before=prior, buyer_direction=buyer,
            supplier_direction=supplier, note=descriptions.get(field, "Commercial impact is not established.")))
